const ES = 1056; const TAG = 'brainIQ';
const existing = []; const errors = [];
for (const it of $input.all()) { const b = it.json.body || {}; if (it.json.statusCode !== 200) errors.push(it.json.statusCode); for (const t of (b.data || [])) existing.push(String(t.term).toLowerCase()); }
const report = []; const add = [];
for (const n of NEW) {
  if (existing.indexOf(n.term.toLowerCase()) >= 0) { report.push({ term: n.term, status: 'already exists - skipped' }); continue; }
  add.push({ term: n.term, description: n.description, caseSensitive: false, translatable: true, forbidden: false, tags: [TAG], translations: [{ langId: ES, translation: n.es, description: n.esn }] });
  report.push({ term: n.term, status: 'to add', es: n.es });
}
const blocked = errors.length > 0 || existing.length < 600;
if (blocked || add.length === 0) return [{ json: { none: true, blocked, errors, nExisting: existing.length, report } }];
return [{ json: { report, nExisting: existing.length, body: { terms: add } } }];

const p = $('Prepare').first().json;
